pub fn generate(_: Command.Context, _: Example.Tag, entry_point: []const u8, result: *BundleV2.DependenciesScanner.Result) !void {
        var react_component_export: []const u8 = "";
        _ = &react_component_export;
        if (findReactComponentExport(result.bundle_v2)) |rc| {
            _ = &rc;
            react_component_export = rc;
        } else {
            _ = Output.errGeneric("No component export found in <b>{f}<r>", .{ bun.fmt.quote(entry_point) });
            _ = Output.flush();
            const writer = Output.errorWriterBuffered();
            _ = try writer.writeAll("\nPlease add an export to your file. For example:\n\n   export default function MyApp() {{\n     return <div>Hello World</div>;\n   }};\n\n");
            _ = Output.flush();
            _ = Global.crash();
        }
        const has_tailwind_in_dependencies = (result.dependencies.contains("tailwindcss") or result.dependencies.contains("bun-plugin-tailwind"));
        var needs_to_inject_tailwind = false;
        _ = &needs_to_inject_tailwind;
        if ((!has_tailwind_in_dependencies)) {
            needs_to_inject_tailwind = hasAnyTailwindClassesInSourceFiles(result.bundle_v2, result.reachable_files);
        }
        const shadcn = (if (enable_shadcn_ui) try getShadcnComponents(result.bundle_v2, result.reachable_files) else bun.StringSet.init(default_allocator));
        const needs_to_inject_shadcn_ui = (shadcn.keys().len > 0);
        if (needs_to_inject_tailwind) {
            _ = try result.dependencies.insert("tailwindcss");
            _ = try result.dependencies.insert("bun-plugin-tailwind");
        }
        if (needs_to_inject_shadcn_ui) {
            _ = try result.dependencies.insert("tw-animate-css");
            _ = try result.dependencies.insert("class-variance-authority");
            _ = try result.dependencies.insert("clsx");
            _ = try result.dependencies.insert("tailwind-merge");
            _ = try result.dependencies.insert("lucide-react");
        }
        const uses_tailwind = (has_tailwind_in_dependencies or needs_to_inject_tailwind);
        _ = result.dependencies.swapRemove("react");
        _ = result.dependencies.swapRemove("react-dom");
        _ = try result.dependencies.insert("react-dom@19");
        _ = try result.dependencies.insert("react@19");
        const dev_dependencies: []const []const u8 = (&.{ "@types/bun", "@types/react@19", "@types/react-dom@19" });
        var template: Template = .ReactSpa;
        _ = &template;
        if (needs_to_inject_shadcn_ui) {
            template = .{ .ReactShadcnSpa = .{ .components = shadcn } };
        } else {
            if (uses_tailwind) {
                template = .ReactTailwindSpa;
            }
        }
        _ = try generateFiles(default_allocator, entry_point, result.dependencies.keys(), dev_dependencies, template, react_component_export);
        _ = Global.exit(0);
}

